{
  "criteria": [
    {
      "id": "task-points",
      "score": 17.5,
      "max": 30,
      "comment": "The letter says where the course was, how long you studied, that you liked it, and asks whether your friend wants to study. It omits when the course took place, who taught it, and what was most difficult."
    },
    {
      "id": "task-length",
      "score": 7,
      "max": 15,
      "comment": "There are five sentences excluding the greeting, rather than at least ten. There is one question rather than the required three to five."
    },
    {
      "id": "letter-form",
      "score": 5,
      "max": 10,
      "comment": "«Привет, Саша» suits a letter to a friend, but there is no sign-off or signature. The short statements have little natural flow between them."
    },
    {
      "id": "vocabulary",
      "score": 13,
      "max": 20,
      "comment": "The everyday words are appropriate and understandable. The range is very narrow for A2: there is no description of the teacher or difficulty and no connectors such as «потому что» or «когда»."
    },
    {
      "id": "grammar",
      "score": 16,
      "max": 25,
      "comment": "«Я закончил» and «Мне нравится» are formed correctly, but «Я учить» and «Ты хотеть» use infinitives instead of conjugated verbs. The letter also has case errors in «курс русский язык», «в Денвер» and «три месяц»."
    }
  ],
  "corrected": "Привет, Саша. Я закончил курс русского языка. Курс был в Денвере. Я учил русский три месяца. Мне нравится курс. Ты хочешь учиться?",
  "changes": [
    {
      "before": "Привет Саша",
      "after": "Привет, Саша",
      "explanation": "Punctuation: set off a direct address with a comma."
    },
    {
      "before": "курс русский язык",
      "after": "курс русского языка",
      "explanation": "Case: after «курс», the name of the subject takes the genitive."
    },
    {
      "before": "в Денвер",
      "after": "в Денвере",
      "explanation": "Case: use the prepositional after «в» to say where something was."
    },
    {
      "before": "Я учить",
      "after": "Я учил",
      "explanation": "Verb form: use the masculine past tense for completed study, not the infinitive."
    },
    {
      "before": "три месяц",
      "after": "три месяца",
      "explanation": "Case after a numeral: «три» takes the genitive singular form «месяца»."
    },
    {
      "before": "Ты хотеть",
      "after": "Ты хочешь",
      "explanation": "Verb conjugation: with «ты», use the present-tense form «хочешь», not the infinitive."
    }
  ],
  "tips": [
    "Before writing, check every bullet point; include when the course took place, the teacher, and the hardest part.",
    "Count your sentences and questions: this task needs at least ten sentences and three to five questions.",
    "Practise conjugating verbs with «я» and «ты», and add a closing line to your next letter."
  ]
}
